(()=>{
const cats=window.NARLIA_CAT_PROFILES;if(!cats)return;
const photo=id=>cats[id]?.photo||'';
function videoId(url){try{const u=new URL(url),host=u.hostname.toLowerCase();let id='';if(host==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(host)){if(u.pathname==='/watch')id=u.searchParams.get('v');else if(/^\/(live|embed|shorts)\//.test(u.pathname))id=u.pathname.split('/')[2];}return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null;}catch(e){return null}}

const fmt=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'Date not recorded';
function age(s){const [y,m,d]=s.split('-').map(Number),n=new Date();let mo=(n.getFullYear()-y)*12+n.getMonth()-m+1;if(n.getDate()<d)mo--;const a=new Date(y,m-1+mo,d);const days=Math.round((Date.UTC(n.getFullYear(),n.getMonth(),n.getDate())-Date.UTC(a.getFullYear(),a.getMonth(),a.getDate()))/86400000);return mo+' month'+(mo===1?'':'s')+(days?', '+days+' day'+(days===1?'':'s'):'');}function ageWeeks(s){const [y,m,d]=s.split('-').map(Number),n=new Date();const days=Math.floor((Date.UTC(n.getFullYear(),n.getMonth(),n.getDate())-Date.UTC(y,m-1,d))/86400000),weeks=Math.floor(days/7);return weeks+' week'+(weeks===1?'':'s');}
const css=`
#cats,#dante,#amara,#narlia-profile{--cl:#294158}
.cat-head{font-size:clamp(24px,3vw,32px);margin:5px 0 12px}.cat-lede{color:var(--muted);line-height:1.6;margin-bottom:20px}
.cat-cards,.cat-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:13px;margin:14px 0}
.cat-card,.cat-panel{background:linear-gradient(150deg,#15283b,#0c1927);border:1px solid var(--cl);border-radius:14px;padding:19px;min-width:0}
.cat-card h3{font-size:24px;margin:8px 0}.cat-card p{color:var(--muted);line-height:1.7;font-size:14px}
.cat-kicker{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#85c9f6;font-weight:800}
.cat-number{font-size:24px;font-weight:800;margin:9px 0}.cat-muted{font-size:13px;color:var(--muted);line-height:1.6}
.cat-button{background:#183650;color:#fff;border:1px solid #35658a;border-radius:8px;padding:10px 14px;font-weight:700;cursor:pointer}
.cat-button:hover,.cat-button:focus-visible{background:#245275;outline:2px solid #71b8e7}
.cat-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,.9fr);gap:14px;margin:15px 0}
.cat-panel h3{margin:0 0 12px}.cat-line{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--cl);padding:12px 0;font-size:14px}
.cat-line:last-child{border:0}.cat-line span{color:var(--muted)}.cat-line b{text-align:right}
.cat-photo{width:100%;max-height:330px;object-fit:cover;border-radius:10px}
.cat-portrait{display:block;width:100%;height:205px;object-fit:cover;border-radius:12px;margin-bottom:12px}
.cat-feature{display:block;width:100%;max-width:360px;aspect-ratio:1/1;object-fit:cover;border-radius:12px;margin-bottom:14px}
.cat-watch-link{display:inline-block;text-decoration:none;margin-top:12px}
.cat-watch-stage{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border-radius:12px;background:#09121c}
.cat-watch-frame{position:absolute;inset:0;width:100%;height:100%;border:0;background:#09121c}
.cat-watch-offline{position:absolute;inset:0;z-index:2;display:grid;place-items:center;overflow:hidden;background:#101e2d}
.cat-watch-offline[hidden]{display:none}
.cat-watch-offline img{width:auto;height:88%;max-width:40%;object-fit:contain;filter:drop-shadow(0 8px 24px #0007)}
.cat-watch-bubble{position:absolute;top:5%;right:5%;max-width:min(76%,320px);padding:12px 18px;border-radius:22px;background:#fffdf4;color:#253446;font-size:clamp(14px,2vw,20px);font-weight:800;line-height:1.25;text-align:center;box-shadow:0 5px 20px #0005}
.cat-watch-bubble:after{content:"";position:absolute;right:22px;bottom:-9px;border-width:10px 0 0 13px;border-style:solid;border-color:transparent transparent transparent #fffdf4}
.cat-watch-note{padding:24px;border:1px dashed #35658a;border-radius:12px;background:#101e2d;line-height:1.7}
.cat-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin:14px 0}
.cat-gallery figure{margin:0;padding:9px;background:#122539;border:1px solid #294158;border-radius:12px}
.cat-gallery img{display:block;width:100%;height:200px;object-fit:cover;border-radius:8px}
.cat-gallery figcaption{color:var(--muted);font-size:12px;line-height:1.5;margin-top:8px}
.cat-gallery figure.special-photo{border-color:#d8ae61;background:linear-gradient(145deg,#382c1c,#122539);box-shadow:0 0 0 1px #d8ae6140}.cat-gallery .special-photo-label{display:inline-block;color:#f1cd82;font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;margin:2px 0 8px}

.cat-growth-chart{display:block;width:100%;height:auto;max-height:560px;object-fit:contain;border-radius:10px;background:#fff}
.cat-journal{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:14px 0}
.cat-journal-entry{background:#122539;border:1px solid var(--cl);border-radius:12px;overflow:hidden}
.cat-journal-entry img{display:block;width:100%;height:180px;object-fit:cover}
.cat-journal-weight{display:grid;place-items:center;height:120px;background:#0c1927;color:#b7ddf7;font-size:25px;font-weight:800}
.cat-journal-copy{padding:12px}.cat-journal-copy strong{display:block}.cat-journal-copy span{display:block;color:var(--muted);font-size:12px;margin-top:3px}.cat-journal-copy p{color:var(--muted);font-size:12px;line-height:1.5;margin:8px 0 0}
@media(max-width:720px){.cat-layout{grid-template-columns:1fr}.cat-card,.cat-panel{padding:15px}.cat-watch-offline img{max-width:58%}}
`;
function go(id){showPage(id==='narlia'?'infographic':id);if(id==='dante'||id==='amara')document.querySelector('[data-page="cats"]')?.classList.add('active');}
function card(id){const c=cats[id],kit=id!=='narlia';return `<article class="cat-card"><div class="cat-kicker">${kit?'Kitten profile':'GPS tracker IAJVTCCE'}</div>${photo(id)?`<img class="cat-portrait" src="${photo(id)}" alt="Portrait of ${c.name}" loading="lazy">`:''}<h3>🐈 ${c.name}</h3><p>${kit?'Born '+fmt(c.born)+' · '+c.sex+'<br>Home since '+fmt(c.joined)+'<br>Last reported: '+c.lastWeightKg.toFixed(1)+' kg':'GPS maps, daily explorer and lifetime history'}</p><button type="button" class="cat-button" data-cat="${kit?id:'narlia-profile'}">View ${c.name}</button></article>`;}
function gallery(c){const items=(c.gallery||[]).map(g=>'<figure'+(g.special?' class="special-photo"':'')+'>'+(g.special?'<span class="special-photo-label">A special moment</span>':'')+'<img src="'+g.src+'" alt="'+g.caption+'" loading="lazy"><figcaption>'+g.caption+'</figcaption></figure>').join('');return `<div class="cat-panel cat-gallery-panel" id="${c.name.toLowerCase()}-photos"><h3>📷 ${c.name}'s photo album · ${(c.gallery||[]).length} photos</h3><p class="cat-muted">Photos selected from the full Auto Photos library${c.name==='Dante'||c.name==='Amara'?'. Shared pictures of Dante and Amara appear in both galleries.':'.'}</p><div class="cat-gallery">${items}</div></div>`;}
function narliaProfile(){const c=cats.narlia,s=document.createElement('section');s.id='narlia-profile';s.className='page';s.innerHTML=`<button type="button" class="cat-button" data-cat="cats">← Our Cats</button><div class="cat-kicker" style="margin-top:20px">Narlia · GPS tracker IAJVTCCE</div><h2 class="cat-head">Narlia's Story</h2><p class="cat-lede">Our tabby explorer, with her own GPS history, maps and records.</p><img class="cat-feature" src="${photo('narlia')}" alt="Narlia, the tabby cat" loading="lazy"><button type="button" class="cat-button" data-cat="infographic">🗺️ Open Narlia's GPS dashboard</button><button type="button" class="cat-button" data-scroll-gallery="narlia">📷 View ${c.gallery.length} photo</button><div class="cat-stats"><div class="cat-card"><div class="cat-kicker">Tracking</div><div class="cat-number">GPS active</div><div class="cat-muted">Tracker IAJVTCCE</div></div><div class="cat-card"><div class="cat-kicker">Exploration history</div><div class="cat-number">On the dashboard</div><div class="cat-muted">Infographic, Lifetime Story, Daily Explorer, Records and Trends</div></div></div>${gallery(c)}`;return s;}
function journalAgeWeeks(born,date){const [y,m,d]=born.split('-').map(Number),[yy,mm,dd]=date.split('-').map(Number);const days=Math.floor((Date.UTC(yy,mm-1,dd)-Date.UTC(y,m-1,d))/86400000);const weeks=Math.floor(days/7);return weeks+' week'+(weeks===1?'':'s');}
function journal(c){const entries=[...(c.weights||[]).map(w=>({date:w.date,weight:w.kg})),...(c.gallery||[]).filter(p=>p.capturedAt).map(p=>({date:p.capturedAt,photo:p}))].sort((a,b)=>b.date.localeCompare(a.date)||(a.weight!=null?-1:1));return '<div class="cat-journal">'+entries.map(e=>{const weeks=journalAgeWeeks(c.born,e.date),weight=e.weight!=null,photo=e.photo;return '<article class="cat-journal-entry">'+(photo?'<img src="'+photo.src+'" alt="'+photo.caption+'" loading="lazy">':'<div class="cat-journal-weight">⚖️ '+e.weight.toFixed(1)+' kg</div>')+'<div class="cat-journal-copy"><strong>'+fmt(e.date)+'</strong><span>'+weeks+' old</span><p>'+(weight?'Weigh-in · '+e.weight.toFixed(1)+' kg'+(e.date===c.weightDate&&c.weightTrendNote?' · '+c.weightTrendNote:''):photo.caption)+'</p></div></article>';}).join('')+'</div>';}
function detail(id){const c=cats[id],s=document.createElement('section');s.className='page';s.id=id;s.innerHTML=`<button type="button" class="cat-button" data-cat="cats">← Our Cats</button><div class="cat-kicker" style="margin-top:20px">${c.name} · kitten profile</div><h2 class="cat-head">${c.name}'s Story</h2><p class="cat-lede">Born ${fmt(c.born)} · ${c.sex} · Joined the family ${fmt(c.joined)}</p><img class="cat-feature" src="${photo(id)}" alt="Portrait of ${c.name}" loading="lazy"><button type="button" class="cat-button" data-cat="kitten-watch">📹 Kitten Watch</button><button type="button" class="cat-button" data-scroll-gallery="${id}">📷 View ${c.gallery.length} photos</button><div class="cat-stats"><div class="cat-card"><div class="cat-kicker">Age today</div><div class="cat-number">${age(c.born)} (${ageWeeks(c.born)})</div></div><div class="cat-card"><div class="cat-kicker">Last reported weight</div><div class="cat-number">${c.lastWeightKg.toFixed(1)} kg</div><div class="cat-muted">Weighed ${fmt(c.weightDate)}</div></div><div class="cat-card"><div class="cat-kicker">Came home</div><div class="cat-number" style="font-size:20px">${fmt(c.joined)}</div></div></div><div class="cat-layout"><div class="cat-panel"><h3>Weight history</h3>${(c.weights||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(w=>`<div class="cat-line"><span>${fmt(w.date)}</span><b>${w.kg.toFixed(1)} kg · ${journalAgeWeeks(c.born,w.date)}</b></div>`).join('')}${c.weightTrendNote?`<p class="cat-muted">${c.weightTrendNote}</p>`:''}</div><div class="cat-panel"><h3>Growth chart</h3><img class="cat-growth-chart" src="${c.growthChart}" alt="${c.name} growth chart" loading="lazy"><p class="cat-muted">Weight by age, with the recorded weigh-ins marked on the chart.</p></div></div><div class="cat-panel"><h3>Milestones</h3><div class="cat-line"><span>Born</span><b>${fmt(c.born)}</b></div><div class="cat-line"><span>Sex</span><b>${c.sex}</b></div><div class="cat-line"><span>Joined the family</span><b>${fmt(c.joined)}</b></div><div class="cat-line"><span>GPS history</span><b>Not tracked yet</b></div><p class="cat-muted">${c.name}'s future GPS data will be separate from Narlia's.</p></div><section class="cat-panel"><h3>Growth &amp; memories journal</h3><p class="cat-muted">Dated weigh-ins and photos, with age shown in weeks at the time of each entry.</p>${journal(c)}</section>${gallery(c)}`;return s;}
function watchPage(){const s=document.createElement('section');s.id='kitten-watch';s.className='page';const url=cats.kittenWatch?.youtubeUrl||'',id=videoId(url),poster='data:image/jpeg;base64,';const offline=`<div class="cat-watch-offline" id="cat-watch-offline" style="--offline-photo:url('${poster}')"><img src="${poster}" alt="Dante and Amara curled up together"><div class="cat-watch-bubble">Come back soon! We're sleeping 😴</div></div>`;const content=id?`<div class="cat-watch-stage"><div class="cat-watch-frame" id="cat-watch-player"></div>${offline}</div>`:offline;s.innerHTML=`<button type="button" class="cat-button" data-cat="cats">← Our Cats</button><div class="cat-kicker" style="margin-top:20px">Dante and Amara</div><h2 class="cat-head">📹 Kitten Watch</h2><p class="cat-lede">The live camera is silent. When the stream is offline, the kittens will let you know when they're sleeping.</p>${content}`;if(id){const mount=()=>{if(!window.YT?.Player)return;new YT.Player('cat-watch-player',{width:'100%',height:'100%',videoId:id,playerVars:{autoplay:1,mute:1,playsinline:1,controls:0,rel:0},events:{onReady:e=>{const p=e.target,card=document.getElementById('cat-watch-offline');p.mute();p.setVolume(0);p.playVideo();let lastDuration=0,lastGrowthAt=0;const checkLive=setInterval(()=>{if(!card?.isConnected){clearInterval(checkLive);return;}const now=Date.now(),state=p.getPlayerState(),duration=p.getDuration();if(duration>0&&lastDuration>0&&duration-lastDuration>=1)lastGrowthAt=now;lastDuration=duration;if(state===YT.PlayerState.PLAYING&&lastGrowthAt&&now-lastGrowthAt<15000){p.mute();p.setVolume(0);card.hidden=true;}else if(!lastGrowthAt||now-lastGrowthAt>18000){card.hidden=false;}},3000);},onStateChange:e=>{const card=document.getElementById('cat-watch-offline');if(!card)return;if(e.data===YT.PlayerState.PLAYING){e.target.mute();e.target.setVolume(0);}else if(e.data===YT.PlayerState.ENDED)card.hidden=false;},onError:()=>{const card=document.getElementById('cat-watch-offline');if(card)card.hidden=false;}}});};if(window.YT?.Player)mount();else{window.onYouTubeIframeAPIReady=mount;const api=document.createElement('script');api.src='https://www.youtube.com/iframe_api';document.head.appendChild(api);}}return s;}
function init(){if(document.getElementById('cats'))return;const nav=document.querySelector('nav'),main=document.querySelector('main');if(!nav||!main)return;const st=document.createElement('style');st.textContent=css;document.head.appendChild(st);const b=document.createElement('button');b.className='tab';b.dataset.page='cats';b.textContent='Our Cats';(nav.querySelector('[data-page="infographic"]')||nav.lastElementChild).after(b);b.onclick=()=>go('cats');const w=document.createElement('button');w.className='tab';w.dataset.page='kitten-watch';w.textContent='Kitten Watch';b.after(w);w.onclick=()=>go('kitten-watch');const s=document.createElement('section');s.id='cats';s.className='page';s.innerHTML=`<div class="cat-kicker">Narlia · Dante · Amara</div><h2 class="cat-head">Our Cats</h2><p class="cat-lede">Three separate stories. Narlia keeps her own GPS history, while Dante and Amara now have dedicated pages for weights and milestones.</p><div class="cat-cards">${card('narlia')}${card('dante')}${card('amara')}</div><div class="cat-layout"><div class="cat-panel"><h3>Welcome home, Dante and Amara</h3><div class="cat-line"><span>Born</span><b>${fmt(cats.dante.born)}</b></div><div class="cat-line"><span>Arrived</span><b>${fmt(cats.dante.joined)}</b></div><div class="cat-line"><span>Dante's last weight</span><b>${cats.dante.lastWeightKg.toFixed(1)} kg</b></div><div class="cat-line"><span>Amara's last weight</span><b>${cats.amara.lastWeightKg.toFixed(1)} kg</b></div><p class="cat-muted">Latest weights recorded ${fmt(cats.dante.weightDate)}. You reported both kittens gained 0.2 kg since last week.</p><button type="button" class="cat-button" data-cat="kitten-watch">📹 Kitten Watch</button></div><div class="cat-panel"><h3>From their early days</h3><img class="cat-photo" src="media/2026-08-25-amara-dante-with-mum.webp" alt="Existing photo of Dante and Amara with their mum" loading="lazy"><p class="cat-muted">Dante and Amara with mum · 25 August 2026</p></div></div>`;main.append(s,narliaProfile(),detail('dante'),detail('amara'),watchPage());main.addEventListener('click',e=>{const photoButton=e.target.closest('[data-scroll-gallery]');if(photoButton){document.getElementById(photoButton.dataset.scrollGallery+'-photos')?.scrollIntoView({behavior:'smooth',block:'start'});return;}const b=e.target.closest('[data-cat]');if(b)go(b.dataset.cat);});window.NARLIA_CATS_BUILD='20261107-live-playing-2';}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();setTimeout(init,250);
})();